    int count = 0; // Contador de apariciones

    // Pedir palabra a contar al usuario
    cout << "Introduzca la palabra a contar: ";
    cin >> wordToCount;

    // Abrir archivo de texto para leer
    ifstream inputFile("archivo.txt");

    if (!inputFile) {
        cout << "Error al abrir el archivo." << endl;
        return 1;
    }

    // Leer línea por línea y contar apariciones
    string line;
    while (getline(inputFile, line)) {
        size_t pos = line.find(wordToCount); // Buscar posición de la palabra en la línea
        while (pos != string::npos) { // Mientras existan más apariciones en la línea
            count++; // Incrementar contador
            pos = line.find(wordToCount, pos + 1); // Buscar siguiente aparición
        }
    }

    // Mostrar resultado
    cout << "El número de apariciones de \"" << wordToCount << "\" en el archivo es: " << count << endl;

